const map = {
  '6': 'in_transit', '7': 'in_transit', '8': 'out_for_delivery',
  '9': 'delivered', '10': 'delivery_exception', '11': 'delivery_exception',
  '17': 'rto', '18': 'rto', 'SHIPPED': 'in_transit', 'DELIVERED': 'delivered'
};

const track = $json.tracking_data?.shipment_track?.[0] || {};
const rawCode = String(track.current_status_code || track.current_status || '').trim();
const mapped = rawCode ? (map[rawCode] || 'unknown') : 'unknown';
const normalized = mapped !== 'unknown' ? mapped : (prev.prev_normalized_status || 'unknown');

const lastScan = track.scans?.slice(-1)[0]?.location || prev.prev_current_location || null;
const edd = track.edd ? String(track.edd).split(' ')[0] : prev.prev_estimated_delivery || null;
const verifiedUrl = track.tracking_url || prev.prev_tracking_url || null;

return {
  json: {
    ...prev,
    new_status: normalized,
    raw_status: track.current_status || prev.prev_raw_status || 'UNKNOWN',
    new_location: lastScan,
    new_eta: edd,
    tracking_url: verifiedUrl,
    raw_payload: $json
  }
};

const prev = $('Determine Courier').item.json;
const map = {
  'in transit': 'in_transit', 'dispatched': 'in_transit', 'out for delivery': 'out_for_delivery',
  'delivered': 'delivered', 'pending': 'delivery_exception', 'failed': 'delivery_exception',
  'consignee unreached': 'delivery_exception', 'rto': 'rto', 'returned': 'rto'
};

const pkg = $json.ShipmentData?.[0]?.Shipment || {};
const rawStatus = (pkg.Status?.Status || '').toLowerCase().trim();
const mapped = rawStatus ? (map[rawStatus] || 'unknown') : 'unknown';
const normalized = mapped !== 'unknown' ? mapped : (prev.prev_normalized_status || 'unknown');

const lastScan = pkg.Scans?.slice(-1)[0]?.ScanDetail?.ScannedLocation || prev.prev_current_location || null;
const edd = pkg.Status?.ExpectedDeliveryDate ? String(pkg.Status.ExpectedDeliveryDate).split('T')[0] : prev.prev_estimated_delivery || null;
const verifiedUrl = pkg.tracking_url || prev.prev_tracking_url || null;

return {
  json: {
    ...prev,
    new_status: normalized,
    raw_status: pkg.Status?.Status || prev.prev_raw_status || 'UNKNOWN',
    new_location: lastScan,
    new_eta: edd,
    tracking_url: verifiedUrl,
    raw_payload: $json
  }
};

const j = $json;
const prevNormalized = j.prev_normalized_status;
const prevRaw = j.prev_raw_status;
const prevLoc = j.prev_current_location;
const prevEta = j.prev_estimated_delivery;
const prevUrl = j.prev_tracking_url;

const newNormalized = j.new_status;
const newRaw = j.raw_status;
const newLoc = j.new_location;
const newEta = j.new_eta;
const newUrl = j.tracking_url;

const statusChanged = newNormalized !== prevNormalized && newNormalized !== 'unknown';
const rawStatusChanged = newRaw && newRaw !== prevRaw;
const locChanged = newLoc && newLoc !== prevLoc;
const etaChanged = newEta && newEta !== prevEta;
const urlChanged = newUrl && newUrl !== prevUrl;

const changed = statusChanged || rawStatusChanged || locChanged || etaChanged || urlChanged;

const importantList = ['out_for_delivery', 'delivered', 'delivery_exception', 'rto', 'lost'];
const isImportant = statusChanged && importantList.includes(newNormalized);

return {
  json: {
    ...j,
    changed,
    isImportant
  }
};

