const query = $input.item.json.query || {};
const mode = query['hub.mode'];
const token = query['hub.verify_token'];
const challenge = query['hub.challenge'];
const expectedToken = $env.META_VERIFY_TOKEN;

if (expectedToken && mode === 'subscribe' && token === expectedToken) {
  return { json: { valid: true, challenge: challenge } };
}
return { json: { valid: false, challenge: null } };

const crypto = require('crypto');
const rawBuffer = $input.item.binary?.data ? Buffer.from($input.item.binary.data.data, 'base64') : null;
if (!rawBuffer || rawBuffer.length === 0) {
  return { json: { valid: false, reason: 'empty_raw_body' } };
}

const headers = $input.item.json.headers || {};
const sigHeader = headers['x-hub-signature-256'] || '';
const secret = $env.META_APP_SECRET || '';
const digest = 'sha256=' + crypto.createHmac('sha256', secret).update(rawBuffer).digest('hex');

function timingSafeEqual(a, b) {
  const bufA = Buffer.from(a); const bufB = Buffer.from(b);
  if (bufA.length !== bufB.length) return false;
  return crypto.timingSafeEqual(bufA, bufB);
}

const valid = sigHeader.length > 0 && secret.length > 0 && timingSafeEqual(sigHeader, digest);
let parsed = {};
try { parsed = JSON.parse(rawBuffer.toString('utf8')); } catch(e) {}

return { json: { valid, parsed, raw_string: rawBuffer.toString('utf8'), channel: 'whatsapp' } };

const crypto = require('crypto');
const rawBuffer = $input.item.binary?.data ? Buffer.from($input.item.binary.data.data, 'base64') : null;
