}

const valid = sigHeader.length > 0 && secret.length > 0 && timingSafeEqual(sigHeader, digest);
let parsed = {};
try { parsed = JSON.parse(rawBuffer.toString('utf8')); } catch(e) {}

return { json: { valid, parsed, raw_string: rawBuffer.toString('utf8'), channel: 'instagram' } };

const crypto = require('crypto');
const p = $json.parsed || {};
const channel = $json.channel;
const value = p.entry?.[0]?.changes?.[0]?.value || p.entry?.[0]?.messaging?.[0] || {};
const message = value?.messages?.[0] || value?.message || {};
const senderId = (message?.from || value?.sender?.id || '').trim();
const text = (message?.text?.body || message?.text || '').trim();

let msgId = message?.id || message?.mid || null;
if (!msgId && senderId) {
  const rawString = $json.raw_string || '';
  msgId = 'hash_' + crypto.createHash('sha256').update(`${channel}:${senderId}:${rawString}`).digest('hex');
}

return {
  json: {
    channel,
    customer_external_id: senderId || null,
    message_id: msgId || null,
    message_text: text,
    received_at: new Date().toISOString()
  }
};

return {
  json: {
    reply_text: "I couldn't verify this chat with an account on file. Please contact customer support or message us from the phone/account linked to your order.",
    channel: $json.channel,
    customer_external_id: $json.customer_external_id,
    message_id: $json.message_id,
    shipment_id: null
  }
};

const text = ($json.message_text || '').trim();
const state = $json.pending_action;
const context = typeof $json.pending_context === 'string' ? JSON.parse($json.pending_context || '[]') : ($json.pending_context || []);

let isValid = false;
let isShipmentDirect = false;
let resolvedShipmentId = null;
let resolvedOrder = null;
let resolvedTracking = null;
let errorReply = null;

if (state === 'awaiting_order_selection') {
  const digit = parseInt(text.replace(/\D/g, ''), 10);
  if (!isNaN(digit) && digit >= 1 && digit <= context.length) {
    isValid = true;
    resolvedOrder = context[digit - 1].order_number;
  } else {
    errorReply = `Please reply with a valid number between 1 and ${context.length} to select your order.`;
  }
} else if (state === 'awaiting_shipment_selection') {
  const digit = parseInt(text.replace(/\D/g, ''), 10);
  if (!isNaN(digit) && digit >= 1 && digit <= context.length) {
    isValid = true;
    isShipmentDirect = true;
    resolvedShipmentId = context[digit - 1].shipment_id;
    resolvedOrder = context[digit - 1].order_number;
  } else {
    errorReply = `Please reply with a valid number between 1 and ${context.length} to select your package.`;
  }
} else if (state === 'awaiting_order_number') {
  const cleanNumeric = text.replace(/[^0-9]/g, '');
  const cleanAlpha = text.replace(/[^a-zA-Z0-9]/g, '');

  if (cleanNumeric.length >= 4 && cleanNumeric.length <= 6 && cleanNumeric === cleanAlpha) {
    isValid = true;
    resolvedOrder = cleanNumeric;
  } else if (cleanAlpha.length >= 8) {
    isValid = true;
    resolvedTracking = cleanAlpha;
  } else {
    errorReply = "Please reply with a valid 4 to 6-digit order number (e.g. #10482) or your courier AWB.";
  }
}

if (!isValid) {
  return {
    json: {
      ...$json,
      is_valid_pending: false,
      reply_text: errorReply || "I couldn't understand that response. Please provide a valid selection.",
      set_pending: state,
      pending_context: $json.pending_context,
      clear_pending: false,
      shipment_id: null
    }
  };
}

return {
  json: {
    ...$json,
    is_valid_pending: true,
    is_shipment_direct: isShipmentDirect,
    shipment_id: resolvedShipmentId,
    order_number: resolvedOrder,
    tracking_number: resolvedTracking,
    clear_pending: true
  }
};

const prev = $('Load Conversation State').item.json;
let raw = {};
try {
  const rawContent = $input.item.json.message?.content || $input.item.json.text || '{}';
  raw = JSON.parse(rawContent);
} catch(e) {}

const allowed = ['TRACK_ORDER', 'NON_TRACKING', 'UNCLEAR'];
let intent = allowed.includes(raw.intent) ? raw.intent : 'UNCLEAR';
let conf = typeof raw.confidence === 'number' ? Math.max(0, Math.min(1, raw.confidence)) : 0;

let orderNum = raw.order_number ? String(raw.order_number).replace(/[^0-9]/g, '') : null;
let trackNum = raw.tracking_number ? String(raw.tracking_number).trim() : null;

const rawText = (prev.message_text || '').trim();
const explicitOrderMatch = rawText.match(/#([0-9]{4,6})\b/);
if (explicitOrderMatch) {
  orderNum = explicitOrderMatch[1];
  intent = 'TRACK_ORDER';
  conf = Math.max(conf, 0.95);
} else if (!orderNum && !trackNum) {
  const cleanAlpha = rawText.replace(/[^a-zA-Z0-9]/g, '');
  const isAllNumeric = /^[0-9]+$/.test(cleanAlpha);

  if (isAllNumeric && cleanAlpha.length >= 4 && cleanAlpha.length <= 6) {
    orderNum = cleanAlpha;
    intent = 'TRACK_ORDER';
    conf = Math.max(conf, 0.9);
  } else if (cleanAlpha.length >= 8) {
    trackNum = cleanAlpha;
    intent = 'TRACK_ORDER';
    conf = Math.max(conf, 0.9);
  }
}

if (conf < 0.65) {
  intent = 'UNCLEAR';
}

return {
  json: {
    ...prev,
    intent,
    order_number: orderNum || null,
    tracking_number: trackNum || null,
    confidence: conf,
    clear_pending: true
  }
};

return {
  json: {
    ...$json,
    reply_text: "That request is outside order tracking. For assistance with returns, products, or store policies, please contact our support team directly.",
    clear_pending: true,
    shipment_id: null
  }
};

return {
  json: {
    ...$json,
    reply_text: "I didn't quite catch that. You can ask me to 'track my order', or send your order number / AWB directly.",
    clear_pending: true,
    shipment_id: null
  }
};

const raw = $json.orders;
const orders = Array.isArray(raw) ? raw.filter(o => o && o.id) : [];
return { json: { ...$json, count: orders.length, orders } };

return {
  json: {
    ...$json,
    reply_text: "I couldn't locate an active order under your account. Please send your 4 to 6-digit order number (e.g. #10482) or tracking AWB.",
    set_pending: 'awaiting_order_number',
    pending_context: null,
    clear_pending: false,
    shipment_id: null
  }
};

const orders = $json.orders || [];
const list = orders.map((o, i) => `${i + 1}. Order #${o.order_number}`).join('\n');
const safeContext = orders.map(o => ({ order_number: o.order_number }));
return {
  json: {
    ...$json,
    reply_text: `I found ${orders.length} active orders:\n${list}\n\nReply with the number (e.g., 1 or 2) to track that shipment.`,
    set_pending: 'awaiting_order_selection',
    pending_context: JSON.stringify(safeContext),
    clear_pending: false,
    shipment_id: null
  }
};

const raw = $json.shipments;
const shipments = Array.isArray(raw) ? raw.filter(s => s && s.shipment_id) : [];
return { json: { ...$json, count: shipments.length, shipments } };

const sList = $json.shipments || [];
const list = sList.map((s, i) => `${i + 1}. Package via ${(s.courier || 'courier').toUpperCase()} (AWB: ${s.tracking_number || 'Pending'})`).join('\n');
const safeContext = sList.map(s => ({
  shipment_id: s.shipment_id,
  order_number: s.order_number,
  courier: s.courier,
  tracking_number: s.tracking_number
}));

return {
  json: {
    ...$json,
    reply_text: `Order #${sList[0]?.order_number} has ${sList.length} packages:\n${list}\n\nReply with the number (e.g., 1 or 2) to track that specific package.`,
    set_pending: 'awaiting_shipment_selection',
    pending_context: JSON.stringify(safeContext),
    clear_pending: false,
    shipment_id: null
  }
};

const s = $json.shipments ? $json.shipments[0] : $json;
if (!s || (!s.shipment_id && !s.exact_found)) {
  return {
    json: {
      ...$json,
      exact_found: false,
      reply_text: "We could not locate that package under your account. Please reply with your order number to try again.",
      clear_pending: true,
      shipment_id: null
    }
  };
}

const hasTracking = !!s.tracking_number && s.tracking_number.trim().length > 0;
const staleThreshold = 15 * 60 * 1000;
const isStale = !s.last_synced_at || (Date.now() - new Date(s.last_synced_at).getTime()) > staleThreshold;
const needsLiveCall = hasTracking && isStale;

return {
  json: {
    ...$json,
    ...s,
    exact_found: true,
    has_tracking: hasTracking,
    needs_live_call: needsLiveCall,
    courier: (s.courier || 'unknown').toLowerCase().trim()
  }
};

const orderNum = $json.order_number || '';
return {
  json: {
    ...$json,
    reply_text: `Order #${orderNum} does not have courier tracking available yet. Tracking information will appear once the shipment is handed to the courier.`,
    clear_pending: true,
    shipment_id: $json.shipment_id || null
  }
};

return {
  json: {
    ...$json,
    reply_text: `Order #${$json.order_number} is dispatched via ${$json.courier}. Live tracking sync is currently unconfigured. Please check your order confirmation email/SMS for tracking updates.`,
    clear_pending: true,
    shipment_id: $json.shipment_id || null
  }
};

const prev = $('Inspect Shipment Details').item.json;
