  '17': 'rto', '18': 'rto', 'SHIPPED': 'in_transit', 'DELIVERED': 'delivered'
};

const track = $json.tracking_data?.shipment_track?.[0] || {};
const rawCode = String(track.current_status_code || track.current_status || '').trim();
const mapped = rawCode ? (map[rawCode] || 'unknown') : 'unknown';
const normalized = mapped !== 'unknown' ? mapped : (prev.normalized_status || 'unknown');

const lastScan = track.scans?.slice(-1)[0]?.location || prev.current_location || null;
const edd = track.edd ? String(track.edd).split(' ')[0] : prev.estimated_delivery || null;
const verifiedUrl = track.tracking_url || prev.tracking_url || null;

return {
  json: {
    shipment_id: prev.shipment_id,
    order_id: prev.order_id,
    customer_id: prev.customer_id,
    order_number: prev.order_number,
    courier: 'shiprocket',
    tracking_number: prev.tracking_number,
    normalized_status: normalized,
    raw_status: track.current_status || prev.raw_status || 'UNKNOWN',
    current_location: lastScan,
    estimated_delivery: edd,
    tracking_url: verifiedUrl,
    synced_at: new Date().toISOString()
  }
};

const prev = $('Inspect Shipment Details').item.json;
const map = {
  'in transit': 'in_transit', 'dispatched': 'in_transit', 'out for delivery': 'out_for_delivery',
  'delivered': 'delivered', 'pending': 'delivery_exception', 'failed': 'delivery_exception',
  'consignee unreached': 'delivery_exception', 'rto': 'rto', 'returned': 'rto'
};

const pkg = $json.ShipmentData?.[0]?.Shipment || {};
const rawStatus = (pkg.Status?.Status || '').toLowerCase().trim();
const mapped = rawStatus ? (map[rawStatus] || 'unknown') : 'unknown';
const normalized = mapped !== 'unknown' ? mapped : (prev.normalized_status || 'unknown');

const lastScan = pkg.Scans?.slice(-1)[0]?.ScanDetail?.ScannedLocation || prev.current_location || null;
const edd = pkg.Status?.ExpectedDeliveryDate ? String(pkg.Status.ExpectedDeliveryDate).split('T')[0] : prev.estimated_delivery || null;
const verifiedUrl = pkg.tracking_url || prev.tracking_url || null;

return {
  json: {
    shipment_id: prev.shipment_id,
    order_id: prev.order_id,
    customer_id: prev.customer_id,
    order_number: prev.order_number,
    courier: 'delhivery',
    tracking_number: prev.tracking_number,
    normalized_status: normalized,
    raw_status: pkg.Status?.Status || prev.raw_status || 'UNKNOWN',
    current_location: lastScan,
    estimated_delivery: edd,
    tracking_url: verifiedUrl,
    synced_at: new Date().toISOString()
  }
};
